# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, J, V, B = "Hélène", "Julien", "Mme Vasseur", "M. Bastide"
D = [
(None, "Vendredi 11 décembre, 18 h 40. La salle est repeinte, l'ardoise toute neuve brille. Quarante couverts sont dressés. Julien ajuste les verres, Hélène sort de la cuisine, tablier propre.", "12월 11일 금요일 오후 6시 40분. 홀은 새로 칠해졌고 새 칠판이 반짝인다. 마흔 명분 상이 차려졌다. 쥘리앵은 잔을 맞추고, 엘렌은 깨끗한 앞치마 차림으로 주방에서 나온다."),
(J, "Alors, chef, tu respires ? Tu as l'air d'un soldat avant l'assaut.", "그래, 셰프, 숨은 쉬고 있어? 돌격 직전의 군인 같은 표정이야."),
(H, "Je respire à moitié. Quarante personnes, Julien. Quarante avis.", "반쯤은 쉬고 있어. 마흔 명이야, 쥘리앵. 의견도 마흔 개고."),
(J, "Quarante amis, plutôt. Ce sont des gens qui ont payé pour qu'on rouvre.", "오히려 친구 마흔 명이지. 우리가 다시 문 열라고 돈을 낸 사람들이잖아."),
(H, "Justement. Ils sont gentils, donc ils n'oseront pas dire la vérité.", "그래서 더 문제야. 친절하니까 진실을 말 못 할 거야."),
(J, "C'est pour ça qu'on a les fiches. Regarde, une note de un à cinq par plat.", "그래서 평가 카드가 있잖아. 봐, 요리마다 1점에서 5점까지 점수를 매겨."),
(H, "Et une ligne libre pour les commentaires. Qu'ils soient honnêtes, s'il te plaît.", "그리고 자유 의견란 한 줄. 솔직하게 써 달라고 말해 줘."),
(J, "Je leur dirai : plus vous êtes sévères, plus on vous aime. Ça marche toujours.", "이렇게 말할게. 엄격할수록 더 사랑받으신다고. 늘 통하지."),
(None, "La porte s'ouvre. Mme Vasseur entre, droite comme un piquet, son sac serré contre elle. Henri la suit, un bouquet à la main.", "문이 열린다. 바쉐 부인이 장대처럼 꼿꼿하게, 가방을 꼭 안고 들어온다. 앙리가 꽃다발을 들고 뒤따른다."),
(V, "Bonsoir, Julien. Il est dix-neuf heures moins vingt. Je suis en avance, c'est normal.", "안녕, 쥘리앵. 7시 이십 분 전이네. 일찍 왔지, 당연한 거야."),
(J, "Madame Vasseur, vous êtes toujours la première. Votre table est prête, la sept, près de la fenêtre.", "바쉐 부인, 언제나 가장 먼저 오시네요. 자리 준비됐습니다, 창가 7번입니다."),
(V, "Je vois ça. Les murs sont d'un autre blanc. Un peu froid, non ?", "보여. 벽이 다른 하양이네. 좀 차갑지 않아?"),
(H, "C'est un blanc cassé, madame. Avec le jaune des lampes, le soir, c'est plus chaleureux.", "아이보리 색이에요, 부인. 저녁에 조명의 노란빛이 더해지면 더 아늑해져요."),
(V, "Hélène ! Je ne vous avais pas vue. Vous avez maigri. Vous mangez, au moins ?", "엘렌! 못 봤네요. 살이 빠졌어요. 그래도 먹긴 해요?"),
(H, "Quand je ne goûte pas toute la journée, oui. Je vous promets de me rattraper ce soir.", "하루 종일 맛보기를 안 할 땐 먹죠. 오늘 저녁엔 만회하겠다고 약속드릴게요."),
(V, "Bien. Qu'on ne dise pas que je vous ai laissée mourir de faim.", "좋아요. 내가 당신을 굶겨 죽였다는 말은 나오지 않게 해야지."),
(None, "M. Bastide arrive en manteau de feutre, une cagette de clémentines sous le bras.", "바스티드 씨가 펠트 코트를 입고 귤 한 상자를 옆구리에 끼고 도착한다."),
(B, "Bonsoir, la compagnie ! Je ne viens pas les mains vides. Des clémentines de Corse, pour le dessert.", "안녕들 하시오! 빈손으론 안 왔지. 후식용 코르시카 귤이오."),
(H, "Monsieur Bastide, vous n'étiez pas obligé. Merci, vraiment.", "바스티드 씨, 그러실 필요 없었는데요. 정말 고마워요."),
(B, "Obligé ? C'est moi qui me suis régalé en regardant votre menu. Du poireau, du potimarron, c'est ma saison !", "필요요? 메뉴를 보면서 내가 더 즐거웠소. 대파에 단호박이라니, 내 계절이오!"),
(J, "Installez-vous, monsieur Bastide, à la table douze avec vos voisins producteurs.", "자리에 앉으세요, 바스티드 씨. 12번 테이블에 이웃 생산자분들과 함께요."),
(None, "19 h 15. La salle se remplit. Les conversations montent, les verres tintent. Hélène retourne en cuisine.", "오후 7시 15분. 홀이 가득 찬다. 말소리가 높아지고 잔이 부딪친다. 엘렌이 주방으로 돌아간다."),
(J, "Mesdames et messieurs, bonsoir et merci d'être là. Ce soir, vous êtes nos premiers juges.", "신사 숙녀 여러분, 안녕하세요, 와 주셔서 감사합니다. 오늘 저녁 여러분은 저희의 첫 심사위원입니다."),
(J, "Sur chaque table, une fiche. Notez de un à cinq, et surtout, dites-nous ce que vous pensez.", "테이블마다 카드가 있습니다. 1점에서 5점으로 매겨 주시고, 무엇보다 생각하시는 바를 말씀해 주세요."),
(V, "De un à cinq ? Moi, je note à ma façon. Mon mari, il met toujours cinq.", "1점에서 5점이라고? 나는 내 방식대로 매길 거야. 우리 남편은 늘 5점을 줘."),
(J, "Henri est un homme sage. Mais vous, madame, vous êtes une experte.", "앙리 씨는 현명한 분이시죠. 하지만 부인은 전문가세요."),
(V, "Flatteur. Apportez-moi la soupe à l'oignon, je veux voir si elle est à la hauteur.", "아첨꾼이구먼. 양파 수프 가져와 봐요, 수준에 맞는지 볼 테니."),
(None, "La soupe arrive, croûte dorée, vapeur épaisse. Mme Vasseur plante sa cuillère et attend un instant.", "수프가 나온다. 노릇한 껍질에 짙은 김이 오른다. 바쉐 부인이 숟가락을 꽂고 잠시 기다린다."),
(V, "Hum. Ça, c'est de l'oignon. Doux, presque sucré, et ce bouillon qui a du caractère.", "음. 이게 양파지. 부드럽고 거의 달콤한데, 육수에 성격이 있네."),
(J, "Vous aimez ? Le chef a ajouté une goutte de vinaigre de xérès au dernier moment.", "마음에 드세요? 셰프가 마지막에 셰리 식초를 한 방울 넣었답니다."),
(V, "Ça relève sans piquer. Bien vu. Mais le fromage est un peu trop épais, il couvre tout.", "자극 없이 맛을 끌어올리네. 잘했어. 그런데 치즈가 좀 두꺼워서 다 덮어 버려."),
(J, "Je le dirai à Hélène. Une couche plus fine, c'est noté.", "엘렌한테 전할게요. 치즈를 더 얇게, 적어 두겠습니다."),
(V, "Et sur la fiche, je mets quatre. Pas cinq. Cinq, c'est quand on pleure de plaisir.", "그리고 카드에는 4점을 줄 거야. 5점은 아니고. 5점은 기뻐서 울 때 주는 거지."),
(B, "Alors moi, je pleure déjà. Ce velouté de potimarron, c'est de la soie, du velours !", "그럼 난 벌써 울고 있소. 이 단호박 벨루테는 비단이고 벨벳이오!"),
(H, "Merci, monsieur Bastide. Vous trouvez qu'il manque quelque chose ?", "고마워요, 바스티드 씨. 뭔가 모자란 게 있다고 느끼세요?"),
(B, "Un tout petit peu de poivre, et il faut que les châtaignes croquent davantage. Le reste, c'est un régal.", "후추를 아주 조금, 그리고 밤이 더 바삭하게 씹히면 좋겠소. 나머지는 훌륭하오."),
(H, "Les châtaignes, je les repasse au four trois minutes avant de servir. Compris.", "밤은 서빙 직전에 오븐에 삼 분 더 돌릴게요. 알겠습니다."),
(B, "Voilà, c'est ça, un chef qui écoute. C'est rare, ma petite.", "그래, 그거요, 귀 기울이는 셰프. 흔치 않다니까."),
(V, "Dites, Julien, sur l'ardoise, en haut : « Merci à vous 1 237. » C'est quoi, ce chiffre ?", "저기, 쥘리앵, 칠판 맨 위에 « 감사합니다 1 237 » 이라고 적혀 있네. 이 숫자는 뭐지?"),
(J, "C'est le nombre de personnes qui ont donné pour la réouverture. Une par une, avec leur nom dans le carnet.", "재개점을 위해 기부해 주신 분들의 수예요. 한 분 한 분, 수첩에 이름이 적혀 있어요."),
(V, "Mille deux cent trente-sept. Il y a plus de monde que dans mon immeuble et mon quartier réunis.", "천이백삼십칠. 우리 건물이랑 동네를 합친 것보다 많네."),
(B, "Et moi, je suis le mille deux cent trente-troisième. Je l'ai demandé à Chloé, je voulais savoir.", "나는 천이백삼십삼 번째요. 클로에한테 물어봤지, 알고 싶어서."),
(V, "Vous, un numéro ? Vous avez de la chance d'avoir un nom, Bastide.", "당신이 번호라니? 이름이 있는 걸 다행으로 알아요, 바스티드."),
(B, "Ha ha ! Madame Vasseur, vous êtes la seule à me faire rougir.", "하하! 바쉐 부인, 나를 얼굴 붉히게 하는 건 당신뿐이오."),
(J, "Hélène, retour de la table cinq : la salade d'endives est jolie mais un peu amère.", "엘렌, 5번 테이블에서 돌아온 의견이에요. 엔다이브 샐러드는 예쁘지만 약간 써요."),
(H, "L'endive, c'est son caractère. Je rajoute un peu de miel dans la vinaigrette.", "엔다이브는 원래 그런 성격이에요. 비네그레트에 꿀을 조금 더 넣을게요."),
(J, "Et une dame demande si la poire est pochée dans du vin ou dans du jus.", "그리고 어떤 부인께서 배가 와인에 졸여진 건지 주스에 졸여진 건지 물으세요."),
(H, "Du vin rouge, avec cannelle et anis. Dis-lui que l'alcool s'évapore à la cuisson.", "레드 와인에 계피랑 팔각이에요. 알코올은 조리 중에 날아간다고 전해 줘."),
(None, "20 h 05. Les plats arrivent. La salle se tait peu à peu, on n'entend plus que les fourchettes.", "저녁 8시 5분. 메인이 나온다. 홀이 점점 조용해지고, 포크 소리만 들린다."),
(V, "Julien, venez. La blanquette, on la mange avec les yeux d'abord. Ce n'est pas du blanc, c'est de l'ivoire.", "쥘리앵, 이리 와 봐요. 블랑케트는 먼저 눈으로 먹는 거야. 흰색이 아니라 상아색이네."),
(J, "Et maintenant, avec la bouche ? Je vous écoute.", "그럼 이제 입으로는요? 들어 볼게요."),
(V, "La viande fond, la sauce est onctueuse. Mais... il y a un petit goût de citron qui me gêne.", "고기는 녹고 소스는 부드러운데... 레몬 맛이 약간 신경 쓰여."),
(J, "Trop de citron ? Ou juste un peu trop présent ?", "레몬이 너무 많나요? 아니면 약간 도드라지는 건가요?"),
(V, "Un peu trop présent. Marthe en mettait deux gouttes, pas cinq.", "약간 도드라져. 마르트는 두 방울만 넣었지, 다섯 방울이 아니라."),
(J, "Je file en cuisine. Elle va adorer vous entendre parler de sa mère.", "주방에 다녀올게요. 어머님 이야기를 해 주시면 엘렌이 정말 좋아할 거예요."),
(H, "J'ai tout entendu depuis le passe, Julien. Deux gouttes. Je corrige tout de suite.", "나 패스에서 다 들었어, 쥘리앵. 두 방울. 바로 고칠게."),
(None, "20 h 50. Hélène goûte la poule au pot au passe. Julien lui tend une cuillère propre.", "저녁 8시 50분. 엘렌이 패스에서 풀레 오 포를 맛본다. 쥘리앵이 깨끗한 숟가락을 건넨다."),
(H, "Hum. Il lui faut du sel. Et une feuille de laurier de plus. Voilà, c'est ça qui manquait.", "음. 소금이 필요해. 월계수잎도 하나 더. 그래, 이게 모자랐던 거야."),
(J, "Karim demande si tu veux qu'il refasse le beurre blanc pour les trois dernières tables.", "카림이 마지막 세 테이블을 위해 뵈르 블랑을 다시 만들까 물어봐."),
(H, "Non, il est parfait. Dis-lui de garder son énergie pour le dessert. Il en aura besoin.", "아니, 완벽해. 디저트에 쓰려고 힘을 아끼라고 해. 필요할 거야."),
(J, "Et Chloé dit que l'ardoise tient bien. Plus personne ne regarde le plafond, tout le monde regarde son assiette.", "그리고 클로에가 칠판은 잘 있대. 이제 아무도 천장 안 보고 다들 접시만 봐."),
(H, "Parfait. C'est bon signe quand on se tait pour manger.", "좋아. 먹느라 조용해지는 건 좋은 신호야."),
(J, "Autre retour : la joue de bœuf est tendre, mais le jus est un peu court.", "또 다른 의견이에요. 소 볼살은 부드러운데 소스가 좀 부족하대요."),
(H, "Court ? Il y avait assez de jus quand je l'ai goûté. Ils en veulent plus ?", "부족하다고? 내가 맛볼 땐 소스가 충분했는데. 더 달라는 거야?"),
(J, "Ils veulent surtout le tremper avec du pain. Ils trouvent qu'il est trop bon pour le laisser.", "무엇보다 빵에 찍어 먹고 싶대요. 남기기엔 너무 맛있다면서."),
(H, "Alors, double portion de jus. Ça, c'est le meilleur compliment du monde.", "그럼 소스를 두 배로 줄게. 그게 세상에서 제일 좋은 칭찬이지."),
(B, "Mademoiselle Hélène, votre cabillaud, il est parfait. La peau croustille, la chair est nacrée.", "엘렌 양, 이 대구는 완벽하오. 껍질은 바삭하고 살은 진주빛이오."),
(H, "Et le beurre blanc ? Il ne s'est pas séparé ?", "뵈르 블랑은요? 분리되지 않았어요?"),
(B, "Pas une seule goutte d'huile au bord de l'assiette. Il est satiné, léger, avec juste ce qu'il faut d'acidité.", "접시 가장자리에 기름 한 방울 없소. 윤기 나고 가볍고 산미도 딱 알맞소."),
(H, "Merci. Karim a passé une demi-heure à le monter, ce soir.", "고마워요. 카림이 오늘 저녁 삼십 분 동안 그걸 만들었어요."),
(B, "Dites-lui que son beurre vaut mon beurre de Normandie. Et ce n'est pas un compliment qu'on fait à n'importe qui !", "그 친구에게 전해 주시오, 그 버터가 내 노르망디 버터만큼 좋다고. 아무한테나 하는 칭찬이 아니오!"),
(None, "Un convive voisin lève la main. Julien se précipite, un carnet à la main.", "이웃 손님 한 명이 손을 든다. 쥘리앵이 수첩을 들고 달려간다."),
(J, "Oui, monsieur ? Tout va bien ?", "네, 손님? 다 괜찮으신가요?"),
(J, "Il dit que la poule au pot est rustique et généreuse, mais un peu fade côté légumes.", "손님 말로는 풀레 오 포가 투박하고 푸짐하지만 채소 쪽이 약간 싱겁대요."),
(H, "Fade ? Les légumes cuisent dans le bouillon, ils prennent le goût de la poule.", "싱겁다고? 채소는 육수 안에서 익으니까 닭 맛이 배는데."),
(J, "Peut-être qu'un peu de gros sel dessus, à la table ? Comme dans le carnet.", "혹시 식탁에서 굵은 소금을 위에 약간 얹는 건 어때요? 수첩에 있는 것처럼요."),
(H, "Oui. Un petit bol de gros sel et de moutarde sur chaque table. Tu as raison.", "그래. 테이블마다 굵은 소금과 머스터드를 작은 그릇에 담아 놓자. 네 말이 맞아."),
(J, "Je reprends mon rôle favori : celui qui a toujours raison.", "내가 제일 좋아하는 역할로 돌아간다. 항상 맞는 사람."),
(H, "Ne t'emballe pas. Va resservir de l'eau à la douze.", "너무 들뜨지 마. 12번 테이블에 물 따라 드려."),
(V, "Hélène, venez une seconde. Je veux vous dire un mot avant le dessert.", "엘렌, 잠깐만 와 봐요. 디저트 전에 한마디 하고 싶어요."),
(H, "Je viens, madame Vasseur. Un problème avec la blanquette ?", "갑니다, 바쉐 부인. 블랑케트에 문제가 있나요?"),
(V, "Non, non. Julien m'a redonné une assiette corrigée. Deux gouttes de citron, c'est exactement ça.", "아니, 아니. 쥘리앵이 고친 접시를 다시 갖다 줬어요. 레몬 두 방울, 딱 그거예요."),
(H, "Soulagement. J'ai cru que vous alliez me mettre un deux.", "휴, 다행이네요. 2점 주실 줄 알았어요."),
(V, "Un deux ? À vous ? Ce serait un crime. Ce soir, c'est un cinq.", "2점? 당신한테? 범죄일 거예요. 오늘 저녁은 5점이에요."),
(H, "Un cinq ? Vous aviez dit qu'un cinq, c'est quand on pleure de plaisir.", "5점이요? 5점은 기뻐서 울 때 주신다고 하셨잖아요."),
(V, "Eh bien... regardez-moi. Je suis assise, je mange la blanquette de Marthe, et il fait chaud dans mon cœur.", "그러니까... 나를 봐요. 앉아서 마르트의 블랑케트를 먹고 있는데 마음이 따뜻해요."),
(H, "Vous pleurez, madame Vasseur ?", "우시는 거예요, 바쉐 부인?"),
(V, "Je ne pleure pas. C'est la vapeur de la sauce. Retournez en cuisine, vous allez me gâter la soirée.", "안 울어요. 소스 김 때문이에요. 주방에 돌아가요, 내 저녁을 망치겠어요."),
(H, "À vos ordres. Je vous envoie la tarte Tatin dans cinq minutes.", "분부대로 하겠습니다. 오 분 뒤에 타르트 타탱을 보내 드릴게요."),
(None, "21 h 10. Les desserts circulent. Les fiches se remplissent. Julien en ramasse une pile.", "저녁 9시 10분. 디저트가 오간다. 카드가 채워지고 있다. 쥘리앵이 한 무더기를 걷는다."),
(J, "Hélène, je te lis les premiers résultats. Soupe à l'oignon : quatre virgule trois sur cinq.", "엘렌, 첫 결과를 읽어 줄게. 양파 수프, 5점 만점에 4.3."),
(H, "Quatre virgule trois. Pas mal du tout. Et la blanquette ?", "4.3. 나쁘지 않아. 블랑케트는?"),
(J, "Quatre virgule six, mais deux personnes ont mis un trois à cause du citron. Corrigé depuis.", "4.6이야. 레몬 때문에 두 명이 3점을 줬어. 지금은 고쳐졌고."),
(H, "Le cabillaud ?", "대구는?"),
(J, "Quatre virgule huit. La note la plus haute du soir, avec la tarte Tatin.", "4.8. 타르트 타탱과 함께 오늘 저녁 최고점이야."),
(H, "Pas la poule au pot, alors ?", "그럼 풀레 오 포는 아니고?"),
(J, "Quatre virgule un. Le point faible, c'est surtout l'assaisonnement, d'après les commentaires.", "4.1. 의견을 보면 약점은 주로 간이야."),
(H, "D'accord. Une pincée de sel, un brin de thym dans le bouillon, et on rattrape.", "알았어. 소금 한 꼬집, 육수에 타임 한 가지를 넣으면 만회할 수 있어."),
(None, "Mme Vasseur se lève et vient vers eux, la tarte Tatin à moitié mangée, la fourchette en main.", "바쉐 부인이 일어나 두 사람 쪽으로 온다. 반쯤 먹은 타르트 타탱과 포크를 들고."),
(V, "Cette Tatin... Les pommes sont caramélisées à point, pas amères. La pâte croque sous la dent.", "이 타탱... 사과가 딱 알맞게 캐러멜화됐고 쓴맛도 없어. 반죽은 씹을 때 바삭해."),
(H, "C'est la recette de ma mère, madame. Presque mot pour mot.", "엄마 레시피예요, 부인. 거의 한 글자도 안 바꿨어요."),
(V, "Presque ? Qu'avez-vous changé, mon enfant ?", "거의라고요? 뭘 바꿨죠, 얘야?"),
(H, "Une pincée de fleur de sel sur le caramel. Maman l'avait écrit, en marge, au crayon.", "캐러멜 위에 플뢰르 드 셀 한 꼬집. 엄마가 여백에 연필로 적어 두셨거든요."),
(V, "Elle avait du goût, votre mère. Elle en avait toujours.", "당신 어머니는 감각이 있었어요. 언제나 있었지."),
(J, "Madame Vasseur, vous voulez bien dire quelques mots à la salle ? Les gens vous regardent.", "바쉐 부인, 홀 전체에 몇 말씀 해 주시겠어요? 다들 부인을 보고 계세요."),
(V, "Moi ? Je déteste parler en public. Enfin... si c'est pour Marthe.", "내가? 사람들 앞에서 말하는 거 아주 싫어하는데. 그래도... 마르트를 위해서라면."),
(None, "Elle tape doucement sa cuillère contre son verre. Le silence se fait.", "그녀가 숟가락으로 잔을 가볍게 두드린다. 조용해진다."),
(V, "Mesdames, messieurs. Je viens ici depuis trente ans. J'ai connu les bons jours et les mauvais.", "신사 숙녀 여러분. 저는 삼십 년 동안 이곳에 다녔습니다. 좋은 날도 나쁜 날도 겪었어요."),
(V, "Ce soir, j'ai retrouvé le goût de la maison. Et je vous le dis : ce n'est pas un repas test, c'est un retour.", "오늘 저녁 저는 이 집의 맛을 되찾았어요. 그리고 말씀드립니다. 이건 시식회가 아니라 귀환이에요."),
(B, "Bravo, madame Vasseur ! Un retour, et un retour en beauté !", "브라보, 바쉐 부인! 귀환이고, 아름다운 귀환이오!"),
(H, "Merci, madame. Merci à tous. Votre générosité nous a ouvert la porte, ce soir, c'est à nous de la tenir ouverte.", "감사합니다, 부인. 모두 감사해요. 여러분의 마음이 문을 열어 주셨고, 이제 문을 열어 두는 건 저희 몫이에요."),
(None, "Applaudissements. Hélène baisse la tête, les yeux brillants. Julien lui tend un verre d'eau.", "박수가 터진다. 엘렌이 고개를 숙이는데 눈이 반짝인다. 쥘리앵이 물 한 잔을 건넨다."),
(J, "Bois. Et ne pleure pas, ça gâche le maquillage. Tu n'en portes pas, mais quand même.", "마셔. 그리고 울지 마, 화장 망친다. 안 하지만, 그래도."),
(H, "Idiot. Bon, il est dix heures. Il y a encore trente personnes qui attendent leur café.", "바보. 자, 열 시야. 아직 커피를 기다리는 사람이 서른 명이나 있어."),
(B, "Et du digestif, ma belle ! Une goutte de poire pour la route ?", "그리고 식후주도요, 아가씨! 가는 길에 서양배 증류주 한 방울 어떻소?"),
(H, "Monsieur Bastide, vous allez conduire. Je vous offre plutôt une clémentine.", "바스티드 씨, 운전하셔야죠. 대신 귤을 하나 드릴게요."),
(B, "Vendue ! Mais je garde la dernière rasade pour mardi, pour fêter la réouverture.", "좋소! 하지만 마지막 한 모금은 화요일 재개점 축하 때를 위해 아껴 두겠소."),
(V, "Julien, avant de partir. Ma table, mardi, à midi. La sept, bien sûr.", "쥘리앵, 가기 전에. 화요일 정오에 내 테이블. 당연히 7번이에요."),
(J, "Réservée depuis le jour où on a cloué les planches à la fenêtre, madame. Elle vous attend.", "창문에 판자를 대던 그날부터 예약돼 있어요, 부인. 기다리고 있답니다."),
(V, "Bien. Et ne la donnez à personne, même si le président de la République se présente.", "좋아요. 대통령이 와도 그 자리를 누구에게도 주지 말아요."),
(J, "Même au président. Je lui proposerai la huit, avec vue sur la sept.", "대통령에게도요. 8번을 권해 드릴게요, 7번이 보이는 자리로."),
(V, "Vous êtes impossible, mon garçon. C'est pour ça que je vous aime bien.", "당신은 못 말려요, 젊은이. 그래서 좋아하는 거예요."),
(B, "Allez, Henri, on y va. Les femmes ont parlé, les hommes obéissent.", "자, 앙리, 갑시다. 여자들이 말했으니 남자들은 따르는 거요."),
(V, "Obéir, lui ? Henri n'a jamais obéi de sa vie. Il a juste appris à dire oui.", "복종? 앙리가요? 평생 복종한 적 없어요. 그냥 네라고 말하는 법을 배웠을 뿐이지."),
(None, "22 h 40. La salle se vide. Hélène et Julien rangent les fiches sur le comptoir. Quarante cartes, quarante sourires.", "밤 10시 40분. 홀이 비어 간다. 엘렌과 쥘리앵이 카드를 계산대에 정리한다. 카드 마흔 장, 미소 마흔 개."),
(J, "Résultat final : moyenne générale de quatre virgule cinq. Et trente et un commentaires qui disent merci.", "최종 결과, 전체 평균 4.5점. 그리고 고맙다는 의견이 서른한 개야."),
(H, "Quatre virgule cinq... Je ne m'attendais pas à ça. Je m'attendais à pire.", "4.5... 이럴 줄은 몰랐어. 더 나쁠 줄 알았거든."),
(J, "Tu t'attends toujours à pire. C'est ton défaut, et ton talent.", "넌 늘 더 나쁜 걸 예상하지. 네 단점이자 재능이야."),
(H, "Demain matin, on corrige : citron, sel, fromage, jus. Et mardi, on ouvre.", "내일 아침에 고치자. 레몬, 소금, 치즈, 소스. 그리고 화요일에 문을 열자."),
(J, "Mardi. Tu réalises ? Dans quatre jours, les vrais clients, ceux qui paient.", "화요일. 실감 나? 나흘 뒤면 진짜 손님이야, 돈 내는 사람들."),
(H, "Je réalise. Et ça me fait peur et envie en même temps.", "실감해. 무섭고 동시에 설레."),
(J, "C'est exactement ce qu'on appelle être vivant.", "바로 그게 살아 있다는 거야."),
(H, "Allez, éteins la salle. Je prends la première fiche en main : « Merci d'avoir rallumé la lumière. »", "자, 홀 불 꺼. 첫 번째 카드를 읽을게. « 다시 불을 켜 줘서 고마워요. »"),
]

